/bin/zsh -lc "python -c \"import pandas as pd,numpy as np; from scipy.optimize import minimize; from scipy.special import expit; d=pd.read_csv('data/nls_ses_processed.csv'); s=d.SES.to_numpy(); b=(d.SAMPLE_RACE=='Black').to_numpy(float); h=(d.SAMPLE_RACE=='Hispanic').to_numpy(float); y=d['BA DEGREE COMPLETED'].to_numpy(float); A={'full':np.c_[np.ones(len(d)),s,b,h,s*b,s*h],'no_h_int':np.c_[np.ones(len(d)),s,b,h,s*b],'no_hisp':np.c_[np.ones(len(d)),s,b,s*b],'both_no_int':np.c_[np.ones(len(d)),s,b,h]};
for k,X in A.items():
 f=lambda q:(np.sum(np.logaddexp(0,X@q)-y*(X@q)),X.T@(expit(X@q)-y)); z=minimize(lambda q:f(q)[0],np.zeros(X.shape[1]),jac=lambda q:f(q)[1],method='BFGS'); print(k,z.x)
\""

